/**
 * Trello Node - Version 1
 * Discriminator: resource=list, operation=getCards
 */


interface Credentials {
  trelloApi: CredentialReference;
  trelloOAuth1Api: CredentialReference;
}

/** Get all the cards in a list */
export type TrelloV1ListGetCardsParams = {
  resource: 'list';
  operation: 'getCards';
  authentication?: 'apiKey' | 'oAuth1' | Expression<string>;
/**
 * The ID of the list to get cards
 */
    id: string | Expression<string>;
/**
 * Whether to return all results or only up to a given limit
 * @default false
 */
    returnAll?: boolean | Expression<boolean>;
/**
 * Max number of results to return
 * @displayOptions.show { returnAll: [false] }
 * @default 20
 */
    limit?: number | Expression<number>;
/**
 * Additional Fields
 * @default {}
 */
    additionalFields?: {
    /** Fields to return. Either "all" or a comma-separated list of fields.
     * @default all
     */
    fields?: string | Expression<string>;
  };
};

export type TrelloV1ListGetCardsOutput = {
  agent?: null;
  badges?: {
    attachments?: number;
    attachmentsByType?: {
      trello?: {
        board?: number;
        card?: number;
      };
    };
    checkItems?: number;
    checkItemsChecked?: number;
    checkItemsEarliestDue?: null;
    comments?: number;
    description?: boolean;
    dueComplete?: boolean;
    fogbugz?: string;
    lastUpdatedByAi?: boolean;
    location?: boolean;
    maliciousAttachments?: number;
    subscribed?: boolean;
    viewingMemberVoted?: boolean;
    votes?: number;
  };
  cardRole?: null;
  checkItemStates?: Array<{
    idCheckItem?: string;
    state?: string;
  }>;
  closed?: boolean;
  cover?: {
    brightness?: string;
    color?: null;
    idPlugin?: null;
    idUploadedBackground?: null;
    size?: string;
    yPosition?: number;
  };
  dateLastActivity?: string;
  desc?: string;
  dueComplete?: boolean;
  email?: null;
  id?: string;
  idBoard?: string;
  idChecklists?: Array<string>;
  idLabels?: Array<string>;
  idList?: string;
  idMembers?: Array<string>;
  idMembersVoted?: Array<string>;
  idShort?: number;
  isTemplate?: boolean;
  labels?: Array<{
    id?: string;
    idBoard?: string;
    idOrganization?: string;
    name?: string;
    nodeId?: string;
    uses?: number;
  }>;
  manualCoverAttachment?: boolean;
  mirrorSourceId?: null;
  name?: string;
  nodeId?: string;
  pinned?: boolean;
  shortLink?: string;
  shortUrl?: string;
  subscribed?: boolean;
  url?: string;
};

export type TrelloV1ListGetCardsNode = {
  type: 'n8n-nodes-base.trello';
  version: 1;
  config: NodeConfig<TrelloV1ListGetCardsParams> & { credentials?: Credentials };
  output?: Items<TrelloV1ListGetCardsOutput>;
};